/*
 * Elf styles. Import AFTER Tailwind in the consumer's main CSS:
 *
 *   @import "tailwindcss";
 *   @import "@xouyi/elfui/styles.css";
 *
 * Theme token files (@xouyi/elfui/themes/*.css) are added by the Nuxt module,
 * or imported manually in non-Nuxt setups.
 */

/* Make Tailwind scan the Elf component sources for utility classes. */
@theme inline {
  --color-background: var(--elf-background);
  --color-foreground: var(--elf-foreground);
  --color-card: var(--elf-card);
  --color-card-foreground: var(--elf-card-foreground);
  --color-popover: var(--elf-popover);
  --color-popover-foreground: var(--elf-popover-foreground);
  --color-primary: var(--elf-primary);
  --color-primary-foreground: var(--elf-primary-foreground);
  --color-secondary: var(--elf-secondary);
  --color-secondary-foreground: var(--elf-secondary-foreground);
  --color-muted: var(--elf-muted);
  --color-muted-foreground: var(--elf-muted-foreground);
  --color-accent: var(--elf-accent);
  --color-accent-foreground: var(--elf-accent-foreground);
  --color-destructive: var(--elf-destructive);
  --color-destructive-foreground: var(--elf-destructive-foreground);
  --color-destructive-text: var(--elf-destructive-text);
  --color-success: var(--elf-success);
  --color-success-foreground: var(--elf-success-foreground);
  --color-warning: var(--elf-warning);
  --color-warning-foreground: var(--elf-warning-foreground);
  --color-border: var(--elf-border);
  --color-input: var(--elf-input);
  --color-ring: var(--elf-ring);

  --radius-sm: max(0px, calc(var(--elf-radius) - 4px));
  --radius-md: max(0px, calc(var(--elf-radius) - 2px));
  --radius-lg: var(--elf-radius);
  --radius-xl: calc(var(--elf-radius) + 4px);
  --radius-badge: var(--elf-radius-pill);
}

@layer base {
  :root {
    color-scheme: dark;
  }

  *,
  ::before,
  ::after {
    border-color: var(--elf-border);
  }

  body {
    background-color: var(--elf-background);
    color: var(--elf-foreground);
  }
}

@keyframes elf-fade-in {
  from { opacity: 0; }
}
@keyframes elf-fade-out {
  to { opacity: 0; }
}
@keyframes elf-zoom-in {
  from { opacity: 0; scale: 0.96; }
}
@keyframes elf-zoom-out {
  to { opacity: 0; scale: 0.96; }
}

@keyframes elf-slide-in-right {
  from { translate: 100% 0; }
}
@keyframes elf-slide-out-right {
  to { translate: 100% 0; }
}
@keyframes elf-slide-in-left {
  from { translate: -100% 0; }
}
@keyframes elf-slide-out-left {
  to { translate: -100% 0; }
}
@keyframes elf-slide-in-top {
  from { translate: 0 -100%; }
}
@keyframes elf-slide-out-top {
  to { translate: 0 -100%; }
}
@keyframes elf-slide-in-bottom {
  from { translate: 0 100%; }
}
@keyframes elf-slide-out-bottom {
  to { translate: 0 100%; }
}

@keyframes elf-toast-in {
  from { opacity: 0; translate: 0 var(--elf-toast-shift, 0.5rem); }
}
@keyframes elf-toast-out {
  to { opacity: 0; scale: 0.96; }
}
@keyframes elf-toast-swipe-out {
  to { opacity: 0; translate: var(--reka-toast-swipe-end-x, 0px) var(--reka-toast-swipe-end-y, 0px); }
}

@keyframes elf-collapsible-down {
  from { height: 0; }
  to { height: var(--reka-collapsible-content-height); }
}
@keyframes elf-collapsible-up {
  from { height: var(--reka-collapsible-content-height); }
  to { height: 0; }
}

@keyframes elf-progress-indeterminate {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}

@media (prefers-reduced-motion: reduce) {
  [data-slot='dialog-overlay'],
  [data-slot='dialog-content'],
  [data-slot='alert-dialog-overlay'],
  [data-slot='alert-dialog-content'],
  [data-slot='sheet-overlay'],
  [data-slot='sheet-content'],
  [data-slot='toast'],
  [data-slot='collapsible-content'],
  [data-slot='accordion-content'] {
    animation: none !important;
  }
}

/* Elf theme (default): pure black neutral surfaces, violet brand accent, 0.625rem radius. */
:root:not([data-theme]),
[data-theme='elf'] {
  --elf-background: #000000;
  --elf-foreground: #fafafa;
  --elf-card: #0a0a0a;
  --elf-card-foreground: #fafafa;
  --elf-popover: #0f0f0f;
  --elf-popover-foreground: #fafafa;
  --elf-primary: oklch(0.7 0.16 293);
  --elf-primary-foreground: oklch(0.15 0.03 295);
  --elf-secondary: #1c1c1c;
  --elf-secondary-foreground: #fafafa;
  --elf-muted: #171717;
  --elf-muted-foreground: #a3a3a3;
  --elf-accent: oklch(0.27 0.06 293);
  --elf-accent-foreground: #fafafa;
  --elf-destructive: oklch(0.55 0.21 25);
  --elf-destructive-foreground: oklch(0.99 0 0);
  --elf-destructive-text: oklch(0.72 0.17 22);
  --elf-success: oklch(0.72 0.17 150);
  --elf-success-foreground: oklch(0.15 0.03 150);
  --elf-warning: oklch(0.82 0.15 85);
  --elf-warning-foreground: oklch(0.2 0.04 85);
  --elf-border: #262626;
  --elf-input: #6b6b6b;
  --elf-ring: oklch(0.7 0.16 293);
  --elf-radius: 0.625rem;
  --elf-radius-pill: 9999px;
}

/* Novatron theme: obsidian black, gold primary, sharp (0px) geometry, zinc borders. */
[data-theme='novatron'] {
  --elf-background: #050505;
  --elf-foreground: #fafafa;
  --elf-card: #09090b;
  --elf-card-foreground: #fafafa;
  --elf-popover: #09090b;
  --elf-popover-foreground: #fafafa;
  --elf-primary: #ffcc00;
  --elf-primary-foreground: #050505;
  --elf-secondary: #18181b;
  --elf-secondary-foreground: #fafafa;
  --elf-muted: #18181b;
  --elf-muted-foreground: #a1a1aa;
  --elf-accent: #27272a;
  --elf-accent-foreground: #fafafa;
  --elf-destructive: #dc2626;
  --elf-destructive-foreground: #ffffff;
  --elf-destructive-text: #f87171;
  --elf-success: #22c55e;
  --elf-success-foreground: #050505;
  --elf-warning: #f59e0b;
  --elf-warning-foreground: #050505;
  --elf-border: #27272a;
  --elf-input: #71717a;
  --elf-ring: #ffcc00;
  --elf-radius: 0px;
  --elf-radius-pill: 0px;
}
